// Configuration — change only these values
const displayName = '';
const secretNames = ['apiKey'];
const publicFields = [];

// Nothing below normally needs to be changed.
const root = $input.first().json;
const credentials = root?.data?.credentials ?? root?.credentials ?? [];
if (!Array.isArray(credentials)) throw new Error('Discovery response did not contain credentials.');
const fieldsOf = (item) => Array.isArray(item?.fields) ? item.fields : [];
const matches = credentials.filter((item) => {
  const name = String(item?.metadata?.displayName ?? '');
  const fields = fieldsOf(item);
  const publicOk = publicFields.every((fieldName) => fields.some((field) => field?.name === fieldName));
  const secretOk = secretNames.every((fieldName) => fields.some((field) => field?.name === fieldName && field?.secret === true));
  return (!displayName || name.toLowerCase().includes(displayName.toLowerCase())) && publicOk && secretOk;
});
if (matches.length !== 1) throw new Error(`Expected exactly one public Credential match, found ${matches.length}.`);
const selected = matches[0];
if (typeof selected.credentialKey !== 'string' || selected.credentialKey.length === 0) throw new Error('Selected Credential has no public credentialKey.');
return [{ json: { credentialKey: selected.credentialKey, secretNames, publicFields, runtimePublic: selected.runtimePublic ?? {} } }];

const data = $input.first().json.data;
const selected = $('Configure Credential').first().json;
if (!data || data.credentialKey !== selected.credentialKey || data.lifecycleState !== 'active' || typeof data.providerKey !== 'string' || !data.secrets || typeof data.secrets !== 'object' || Array.isArray(data.secrets)) throw new Error('Resolve response did not contain a valid active Credential.');
const resolvedNames = Object.keys(data.secrets);
if (resolvedNames.length !== selected.secretNames.length || resolvedNames.some((name) => !selected.secretNames.includes(name)) || selected.secretNames.some((name) => typeof data.secrets[name] !== 'string')) throw new Error('Resolve response did not contain exactly the requested Secret fields.');
return [{ json: { status: 'success', credentialKey: selected.credentialKey, resolvedSecretNames: resolvedNames, timestamp: new Date().toISOString() } }];
